; ---------------------------------------------------------------------------

;%assign tmp   -4
%assign o       8

regflag:
                push    ebp
                mov     ebp, esp
                ;sub    esp, 4
                ;nop
                mov     eax, [ebp+o]
                add     eax, 12
                mov     ecx, [eax]      ; o->basereg
                push    ecx
                call    is_register     ; if (!is_register(o->basereg))
                add     esp, 4
                ;cmp    eax, 0
                ;jz     rf_1
                ;jmp    rf_2
                and	eax, eax
                jnz     rf_2
; ---------------------------------------------------------------------------

rf_1:                                   ; ...
                mov     eax, A_100      ; "invalid operand passed to regflag()"
                push    eax
                ;mov    eax, 0
                sub     eax, eax  
                push    eax
                call    nasm_panic      ; nasm_panic(0, "invalid operand passed to regflag()");
                add     esp, 8

rf_2:                                   ; ...
                mov     eax, [ebp+o]
                add     eax, 12
                mov     ecx, [eax]
                shl     ecx, 3
                ;mov    eax, nasm_reg_flags
                ;add    eax, ecx
                ;mov    [ebp+tmp], eax
                ;mov    eax, [ebp+tmp]
                ;mov    eax, [eax]      ; return nasm_reg_flags[o->basereg];
                ;mov    ecx, [ebp+tmp]
                add     ecx, nasm_reg_flags
                mov     eax, [ecx]   
                add     ecx, 4
                mov     edx, [ecx]
                leave
                retn


