%assign val    -4
%assign o       8
%assign mask    0Ch
%assign _byte   10h

op_evexflags:
                push    ebp
                mov     ebp, esp        ; int val;
                sub     esp, 4
                ;nop
                mov     eax, [ebp+o]
                add     eax, 12
                mov     ecx, [eax]      ; o->basereg
                shl     ecx, 2          ; * int_size (*4)
                mov     eax, nasm_regvals
                add     eax, ecx
                mov     ecx, [eax]
