                mov     ecx, [ebp+mask]
                push    ecx
                movzx   ecx, word [eax] ; o->decoflags
                push    ecx
                mov     eax, [ebp+val]
                push    eax
                call    evexflags ; return evexflags(val, o->decoflags, mask, byte);
                add     esp, 16
                leave
                retn


